def t(k):
    while k % 2 == 0:
        k //= 2
    return k

def h(k):
    return (t(k) % 4 - 1) // 2  # 0 if t(k)%4==1, 1 if t(k)%4==3

# Check which a work: find n such that h(n+j+a)==h(n+j) for all j in range(a)
def check_a(a, max_n=10000):
    for n in range(1, max_n):
        ok = True
        for j in range(a):
            if h(n+j+a) != h(n+j):
                ok = False
                break
        if ok:
            return n
    return None

for a in range(1, 50):
    n = check_a(a)
    if n is not None:
        print(f'a={a}: works, n={n}')
    else:
        print(f'a={a}: NO solution found (searched up to 10000)')
