python3 -c "
def t(k):
    while k % 2 == 0:
        k //= 2
    return k

def h(k):
    return (t(k) % 4 - 1) // 2

# Find all breaks (h(k)==h(k+1)) and alternating run lengths
breaks = []
for k in range(1, 200):
    if h(k) == h(k+1):
        breaks.append(k)

print('Breaks (h(k)==h(k+1)) for k=1..199:', breaks)
print()

# Alternating run lengths
runs = []
start = 1
for k in range(1, 200):
    if h(k) == h(k+1):
        runs.append((start, k, k - start + 1))
        start = k + 1
runs.append((start, 200, 200 - start + 1))
print('Alternating runs (start, end, length):')
for r in runs:
    if r[2] >= 3:
        print(r)
"

